import { Component, OnInit, OnDestroy, Input, Output, EventEmitter, SimpleChanges } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { MatRadioModule } from '@angular/material/radio';
import { NgSelectModule } from '@ng-select/ng-select';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { pageLinkToolEvent } from '../../../../shared/interfaces/preview.interface';
import { DocInfo } from '../../../../pdf/interfaces/pdf.interface';

interface PaginationRange {
  page: number;
  output: number;
}

export interface PageSelection {
  startPage: number;
  endPage: number;
  linkType: string;
}
export interface pageRangeSelector {
  start?: number;
  end?: number;
  cPage: string
}

@Component({
  selector: 'page-range-tool',
  standalone: true,
  imports: [CommonModule, FormsModule, MatRadioModule, NgSelectModule, ButtonComponent],
  templateUrl: './page-range-tool.component.html',
  styleUrl: './page-range-tool.component.scss'
})
export class PageRangeToolComponent implements OnInit, OnDestroy {

  // Page range properties
  linkType: string = 'P';
  startPg: number | null = null;
  endPg: number | null = null;
  @Input() pagginationRenge: PaginationRange[] = [];
  @Input() isIframe: boolean = false;

  @Input() pageRangeSelector: pageRangeSelector;
  @Output() pageRangeSelectorChange: EventEmitter<pageRangeSelector> = new EventEmitter<pageRangeSelector>();

  loading: boolean = false;

  @Input() enablePageRange: boolean;
  @Output() enablePageRangeChange: EventEmitter<boolean> = new EventEmitter<boolean>();

  @Output() onPageRangeToolEvent: EventEmitter<PageSelection> = new EventEmitter<PageSelection>();

  endPageOptions: PaginationRange[] = [];

  @Input() pageRangeTextSelectionData: DocInfo;
  @Output() pageRangeTextSelectionDataChange: EventEmitter<DocInfo> = new EventEmitter<DocInfo>();

  @Output() onEmitEvent: EventEmitter<pageLinkToolEvent> = new EventEmitter<pageLinkToolEvent>();
  ngOnInit() {
    const totalPage = Number(this.pageRangeSelector.cPage.split('-')[1] || 1);

    this.pagginationRenge = Array.from({ length: totalPage }, (_, i) => ({
      page: i + 1,
      output: i + 1
    }));

    this.endPageOptions = this.pagginationRenge;

  }

  ngOnDestroy() {
  }

ngOnChanges(changes: SimpleChanges): void {
  //Called before any other lifecycle hook. Use it to inject dependencies, but avoid any serious work here.
  //Add '${implements OnChanges}' to the class.
    debugger;
}

  closeChild() {
    this.enablePageRange = false;
    this.pageRangeTextSelectionData = null;
    this.pageRangeTextSelectionDataChange.emit(null);
    this.enablePageRangeChange.emit(this.enablePageRange);
  }

  createLink() {

    if (this.pageRangeTextSelectionData) {
      this.enablePageRange = false;
      this.enablePageRangeChange.emit(this.enablePageRange);
      this.onEmitEvent.emit({ event: 'TEXT-SELECTED', data: null });
    }
    else {
      if (!this.startPg || !this.endPg) {
        console.warn('Please select both start and end pages');
        return;
      }
      if (this.endPg >= this.startPg) {
        const linkData: PageSelection = {
          startPage: this.startPg,
          endPage: this.endPg,
          linkType: this.linkType
        };

        this.enablePageRange = false;
        this.enablePageRangeChange.emit(this.enablePageRange);
        this.onPageRangeToolEvent.emit(linkData);
      }
    }
  }

  // Public methods for template
  OnPageSelected(type: string) {
    if (type === 'S' && this.startPg) {
      // Filter end pages to only show after start page
      this.endPageOptions = this.pagginationRenge.filter(
        (p) => p.page > this.startPg!
      );

      // Reset endPg if it's now invalid
      if (this.endPg && this.endPg <= this.startPg) {
        this.endPg = null;
      }
    }
  }

  restrictToNumbers(event: KeyboardEvent) {
    const allowedControlKeys = [
      'Backspace', 'Delete', 'ArrowLeft', 'ArrowRight', 'Tab', 'Home', 'End'
    ];
    const isCtrlCmdCombo = event.ctrlKey || event.metaKey;
    if (isCtrlCmdCombo) {
      return;
    }
    if (allowedControlKeys.includes(event.key)) {
      return;
    }
    const isNumber = /[0-9]/.test(event.key);
    if (!isNumber) {
      event.preventDefault();
    }
  }


}
